def truthy(v): return str(v).strip().lower() in {'true','1','yes'}
active=[r for r in rows if not truthy(r['is_resolved'])]
resolved=[r for r in rows if truthy(r['is_resolved'])]
active_ids={str(r['qid']) for r in active}
market_ids={str(r['qid']) for r in rows}
